from class12_chemistry_opening import pair,section,SOURCE
from class12_chemistry_sync import save
from class12_chemistry_rings import Fig
F=Fig('arrow92');t=F.t;line=F.line
paras=[];layout=[];blocks=[]
def add(e,u,p,kind='paragraph'):
 layout.append({'type':kind,'indices':[len(paras)]});paras.append(pair(e,u,p))
def visual(identity,fn):
 blocks.append({'id':identity,'svg':fn('en'),'svgUrdu':fn('ur'),'svgPashto':fn('ps')});layout.append({'type':'visual','blockId':identity})
N={'2-bromopropane':('2-برومو پروپین','2-بروموپروپان'),'sodium ethanethiolate':('سوڈیم ایتھین تھائیولیٹ','سوډیم ایتان تیولېټ'),'propene':('پروپین','پروپین'),'(minor)':('(چھوٹی)','(لږه)'),'(major)':('(بڑی)','(عمده)'),
   'ethyl isopropyl sulfide':('ایتھائل آئسوپروپائل سلفائیڈ','ایتیل ایزوپروپیل سلفاید'),'methylmagnesium iodide':('میتھائل میگنیشیم آئیوڈائیڈ','میتایل مګنیزیم ایوډایډ'),'tetramethyllead':('ٹیٹرا میتھائل لیڈ','ټیټرا میتایل سرپ'),
   'dimethylzinc':('ڈائی میتھائل زنک','ډای میتایل جست'),'methylmagnesium bromide':('میتھائل میگنیشیم برومائیڈ','میتایل مګنیزیم برومایډ'),'ethylmagnesium chloride':('ایتھائل میگنیشیم کلورائیڈ','ایتیل مګنیزیم کلوراید'),
   'phenylmagnesium bromide':('فینائل میگنیشیم برومائیڈ','فینیل مګنیزیم برومایډ'),'alkyl halide':('الکائل ہیلائیڈ','الکایل هالایډ'),'Grignard reagent':('گرینیارڈ عامل','ګرینیارډ عامل'),'ether':('ایتھر','ایتر')}
def lb(lang,v):return v if lang=='en' else N[v][0 if lang=='ur' else 1]
def thiol(lang):
 s=F.start(140)+t(100,30,'Br',14)+line(100,36,100,52)+t(100,70,'CH₃CHCH₃',16)+t(100,94,lb(lang,'2-bromopropane'),12)+t(270,70,'+  C₂H₅S⁻Na⁺',16)+t(280,94,lb(lang,'sodium ethanethiolate'),12)
 s+=F.arrow(380,460,64)+t(550,70,'CH₃CH=CH₂',16)+t(550,94,lb(lang,'propene'),12)+t(550,110,lb(lang,'(minor)'),12)+t(640,70,'+',16)
 s+=t(730,30,'SC₂H₅',14)+line(730,36,730,52)+t(730,70,'CH₃CHCH₃',16)+t(730,94,lb(lang,'ethyl isopropyl sulfide'),12)+t(730,110,lb(lang,'(major)'),12)
 return s+'</svg>'
def row(lang,items,h=80):
 s=F.start(h);n=len(items)
 for k,(f,name) in enumerate(items):x=850*(k+.5)/n;s+=t(x,35,f,17)+t(x,60,lb(lang,name),12)
 return s+'</svg>'
def prep(lang):return F.start(80)+t(220,35,'R — X  +  Mg',17)+t(200,60,lb(lang,'alkyl halide'),12)+F.arrow(320,430,29,lb(lang,'ether'))+t(560,35,'R — MgX',17)+t(560,60,lb(lang,'Grignard reagent'),12)+'</svg>'
def dietherate(lang):
 s=F.start(150,520)+t(260,82,'Mg',18)+t(150,40,'R',16)+line(160,46,245,72,1.5,'#222','stroke-dasharray="3 3"')+t(150,130,'X',16)+line(160,124,245,90,4)
 s+=F.line(370,40,280,70,2,'#222','marker-end="url(#arrow92)"')+t(420,40,'O(C₂H₅)₂',15)+F.line(370,124,280,92,2,'#222','marker-end="url(#arrow92)"')+t(420,130,'O(C₂H₅)₂',15)
 return s+'</svg>'

visual('chem12-p92-thiolate',thiol)
add('Other factors like temperature and nature of solvent, can also have some effect on the extent of elimination and substitution products.','درجہ حرارت اور محلل کی نوعیت جیسے دوسرے عوامل بھی اخراج اور تبادلے کی پیداواروں کی حد پر کچھ اثر ڈال سکتے ہیں۔','نور عوامل لکه تودوخه او د محلل طبیعت هم د ایستنې او بدلون د محصولاتو پر کچه یو څه اغېز کولی شي.')
add('17.2 Organometallic Compounds (Grignard Reagents)','17.2 آرگینو میٹلک مرکبات (گرینیارڈ عاملین)','17.2 عضوي فلزي مرکبات (ګرینیارډ عاملونه)','heading')
add('All those organic compounds which contain at least one carbon–metal bond in their structures are known as organometallic compounds. You are already familiar with at least one organometallic compound, sodium acetylide (Na⁺⁻C ≡ CH), (Section 16.7.7) which has an ionic bond between carbon and sodium. Organometallic compounds are generally represented by the formula: R–M or Ar–M',
 'وہ تمام نامیاتی مرکبات جن کی ساخت میں کم از کم ایک کاربن–دھات بند ہو، آرگینو میٹلک مرکبات کہلاتے ہیں۔ آپ کم از کم ایک آرگینو میٹلک مرکب، سوڈیم ایسیٹیلائیڈ (Na⁺⁻C ≡ CH)، (حصہ 16.7.7) سے پہلے ہی واقف ہیں جس میں کاربن اور سوڈیم کے درمیان آئنی بند ہے۔ آرگینو میٹلک مرکبات کو عموماً فارمولا R–M یا Ar–M سے ظاہر کیا جاتا ہے۔',
 'هغه ټول عضوي مرکبات چې په جوړښت کې یې لږ تر لږه یو کاربن–فلز تړون وي، عضوي فلزي مرکبات بلل کېږي. تاسې لږ تر لږه له یوه عضوي فلزي مرکب، سوډیم اسیتیلاید (Na⁺⁻C ≡ CH)، (برخه 16.7.7) سره دمخه بلد یاست چې د کاربن او سوډیم ترمنځ ایوني تړون لري. عضوي فلزي مرکبات معمولاً د R–M یا Ar–M فورمول په واسطه ښودل کېږي.')
add('Where, M = Mg, Li, Hg, Cu, Pb, Zn etc. and R- and Ar- represent any alkyl or aryl groups respectively. They are named simply by adding the name of the metal to the organic group bonded directly to the metal. Examples;',
 'جہاں M = Mg، Li، Hg، Cu، Pb، Zn وغیرہ اور R- اور Ar- بالترتیب کسی بھی الکائل یا ایرائل گروپ کو ظاہر کرتے ہیں۔ ان کے نام دھات سے براہِ راست جڑے نامیاتی گروپ کے ساتھ دھات کا نام لگا کر رکھے جاتے ہیں۔ مثالیں؛',
 'چې M = Mg، Li، Hg، Cu، Pb، Zn او نور، او R- او Ar- په ترتیب سره هر الکایل یا اریل ګروپ ښيي. دوی په ساده ډول له فلز سره د مستقیم تړلي عضوي ګروپ سره د فلز د نوم په زیاتولو نومول کېږي. بېلګې؛')
visual('chem12-p92-organometallic-names',lambda l:row(l,[('CH₃ – MgI','methylmagnesium iodide'),('(CH₃)₄Pb','tetramethyllead'),('CH₃ – Zn – CH₃','dimethylzinc')]))
add('Alkyl or aryl magnesium halides (organomagnesium compounds) are commonly known as Grignard reagents. They were discovered, prepared and studied by victor Grignard, therefore, they were named after him as Grignard reagents. They are highly reactive organic compounds, and are used in the synthesis of a large number of organic compounds. Due to this great achievement Grignard was awarded with Nobel Prize in 1912. The general formula of Grignard reagents is, R–MgX where R represent Alkyl group (can also be vinylic or aryl group) and X represent halogen atom. Examples are;',
 'الکائل یا ایرائل میگنیشیم ہیلائیڈز (آرگینو میگنیشیم مرکبات) عام طور پر گرینیارڈ عاملین کہلاتے ہیں۔ انہیں وکٹر گرینیارڈ نے دریافت، تیار اور مطالعہ کیا، اسی لیے ان کا نام ان کے نام پر گرینیارڈ عاملین رکھا گیا۔ یہ انتہائی تعامل پذیر نامیاتی مرکبات ہیں اور بڑی تعداد میں نامیاتی مرکبات کی تیاری میں استعمال ہوتے ہیں۔ اسی عظیم کارنامے پر گرینیارڈ کو 1912 میں نوبل انعام دیا گیا۔ گرینیارڈ عاملین کا عمومی فارمولا R–MgX ہے، جہاں R الکائل گروپ (وائنائلک یا ایرائل گروپ بھی ہو سکتا ہے) اور X ہیلوجن ایٹم ہے۔ مثالیں یہ ہیں؛',
 'الکایل یا اریل مګنیزیم هالایډونه (عضوي مګنیزیمي مرکبات) عموماً د ګرینیارډ عاملونو په نوم پېژندل کېږي. دوی ویکټور ګرینیارډ کشف، جوړ او مطالعه کړل، نو د هغه په نوم ګرینیارډ عاملونه ونومول شول. دوی ډېر تعامل کوونکي عضوي مرکبات دي او د ډېرو عضوي مرکباتو په جوړولو کې کارېږي. د همدې لویې لاسته راوړنې له امله ګرینیارډ ته په 1912 کې د نوبل جایزه ورکړل شوه. د ګرینیارډ عاملونو عمومي فورمول R–MgX دی، چې R الکایل ګروپ (کېدای شي وینایلي یا اریل ګروپ هم وي) او X هالوجني اټوم ښيي. بېلګې دا دي؛')
visual('chem12-p92-grignard-names',lambda l:row(l,[('CH₃ – Mg – Br','methylmagnesium bromide'),('CH₃ – CH₂ – Mg – Cl','ethylmagnesium chloride'),('C₆H₅ – Mg – Br','phenylmagnesium bromide')]))
add('17.2.1 Preparation of Grignard Reagents','17.2.1 گرینیارڈ عاملین کی تیاری','17.2.1 د ګرینیارډ عاملونو چمتو کول','heading')
add('Grignard reagents are prepared in the laboratory by the action of alkyl or aryl halides on freshly prepared magnesium metal in anhydrous or dry ether i.e. diethyl ether or tetrahydrofuran.','گرینیارڈ عاملین تجربہ گاہ میں بے آب یا خشک ایتھر، یعنی ڈائی ایتھائل ایتھر یا ٹیٹرا ہائیڈرو فیوران، میں تازہ تیار شدہ میگنیشیم دھات پر الکائل یا ایرائل ہیلائیڈز کے عمل سے تیار کیے جاتے ہیں۔','ګرینیارډ عاملونه په لابراتوار کې په بې اوبو یا وچ ایتر، یعنې ډای ایتیل ایتر یا ټیټراهایدروفوران کې، پر تازه جوړ شوي مګنیزیم فلز د الکایل یا اریل هالایډونو د عمل په واسطه چمتو کېږي.')
visual('chem12-p92-grignard-prep',prep)
add('It is an example of heterogeneous reaction, in which solid magnesium react with alkyl halide in ether. Grignard reagent cannot be isolated, therefore, its ethereal solution is directly used in the synthetic reactions.','یہ غیر ہم جنس تعامل کی مثال ہے، جس میں ٹھوس میگنیشیم ایتھر میں الکائل ہیلائیڈ سے تعامل کرتی ہے۔ گرینیارڈ عامل کو الگ نہیں کیا جا سکتا، اس لیے اس کا ایتھری محلول براہِ راست تیاری کے تعاملات میں استعمال ہوتا ہے۔','دا د ناهمجنس تعامل بېلګه ده، چې پکې جامد مګنیزیم په ایتر کې له الکایل هالایډ سره تعامل کوي. ګرینیارډ عامل جلا کېدای نه شي، نو د هغه ایتري محلول مستقیم په ترکیبي تعاملونو کې کارېږي.')
add('The ease of formation of Grignard reagent depends upon the nature of both alkyl and aryl group and the nature of halogen. Increasing size of the alkyl group makes the formation of Grignard reagent difficult. For the same alkyl group, the ease of formation increases down the group i.e. from fluorine to iodine. Alkyl magnesium fluorides and chloride are not obtained with good yield. Alkyl iodides are the most reactive but still bromides are used more commonly for preparation of Grignard reagent because bromides are less expensive and less toxic than iodides.',
 'گرینیارڈ عامل بننے کی آسانی الکائل اور ایرائل گروپ دونوں کی نوعیت اور ہیلوجن کی نوعیت پر منحصر ہے۔ الکائل گروپ کا حجم بڑھنے سے گرینیارڈ عامل کا بننا مشکل ہو جاتا ہے۔ ایک ہی الکائل گروپ کے لیے بننے کی آسانی گروپ میں نیچے کی طرف، یعنی فلورین سے آئیوڈین کی طرف، بڑھتی ہے۔ الکائل میگنیشیم فلورائیڈز اور کلورائیڈ اچھی مقدار میں حاصل نہیں ہوتے۔ الکائل آئیوڈائیڈز سب سے زیادہ تعامل پذیر ہیں لیکن پھر بھی گرینیارڈ عامل کی تیاری کے لیے برومائیڈز زیادہ استعمال ہوتے ہیں کیونکہ برومائیڈز آئیوڈائیڈز سے سستے اور کم زہریلے ہیں۔',
 'د ګرینیارډ عامل د جوړېدو اسانتیا د الکایل او اریل ګروپ دواړو پر طبیعت او د هالوجن پر طبیعت پورې اړه لري. د الکایل ګروپ د اندازې زیاتېدل د ګرینیارډ عامل جوړېدل ستونزمن کوي. د ورته الکایل ګروپ لپاره د جوړېدو اسانتیا په ګروپ کې ښکته خوا ته، یعنې له فلورین څخه ایوډین ته، زیاتېږي. الکایل مګنیزیم فلورایډونه او کلوراید په ښه حاصل نه ترلاسه کېږي. الکایل ایوډایډونه تر ټولو ډېر تعامل کوونکي دي خو بیا هم د ګرینیارډ عامل د جوړولو لپاره برومایډونه ډېر کارېږي ځکه برومایډونه له ایوډایډونو ارزانه او لږ زهرجن دي.')
add('Diethyl ether used in the preparation of Grignard reagent plays two important roles. At one hand, it provides a medium for the reaction, at the other hand, it dissolves the Grignard reagent by the process of solvation. Crystalline Grignard reagent obtained by cooling ethereal solution of Grignard reagent, have been found to be dietherate in which magnesium has been coordinated with two molecules of ethers, in addition to having two covalent bonds. The four groups are arranged tetrahedrally around magnesium.',
 'گرینیارڈ عامل کی تیاری میں استعمال ہونے والا ڈائی ایتھائل ایتھر دو اہم کردار ادا کرتا ہے۔ ایک طرف یہ تعامل کے لیے واسطہ فراہم کرتا ہے، دوسری طرف یہ سولویشن کے عمل سے گرینیارڈ عامل کو حل کرتا ہے۔ گرینیارڈ عامل کے ایتھری محلول کو ٹھنڈا کر کے حاصل ہونے والا قلمی گرینیارڈ عامل ڈائی ایتھریٹ پایا گیا ہے جس میں میگنیشیم دو شریک گرفتی بندوں کے علاوہ ایتھر کے دو سالمات سے کوآرڈینیٹ ہوتی ہے۔ یہ چار گروپ میگنیشیم کے گرد چہار سطحی ترتیب میں ہوتے ہیں۔',
 'د ګرینیارډ عامل په جوړولو کې کارېدونکی ډای ایتیل ایتر دوه مهم رولونه لوبوي. له یوې خوا د تعامل لپاره منځنی چاپېریال برابروي، له بلې خوا د سولویشن د بهیر په واسطه ګرینیارډ عامل حلوي. هغه کرسټلي ګرینیارډ عامل چې د ګرینیارډ عامل د ایتري محلول په سړولو ترلاسه کېږي، ډای ایتریټ موندل شوی چې پکې مګنیزیم له دوو کوولانسي تړونونو سربېره د ایتر له دوو مالیکولونو سره همغږی شوی. دا څلور ګروپونه د مګنیزیم شاوخوا په څلورمخي ډول ترتیب شوي.')
visual('chem12-figure17-4',dietherate)
add('Figure 17.4 Tetrahedral dietherate of Grignard reagent.','شکل 17.4 گرینیارڈ عامل کا چہار سطحی ڈائی ایتھریٹ۔','شکل 17.4 د ګرینیارډ عامل څلورمخی ډای ایتریټ.')
add('17.2.2 Reactivity of Grignard Reagents','17.2.2 گرینیارڈ عاملین کی تعامل پذیری','17.2.2 د ګرینیارډ عاملونو تعامل وړتیا','heading')
add('The carbon magnesium bond of Grignard reagent is polar in nature. This is due to higher electronegativity of carbon than magnesium. So the electronic density is lying close to carbon than magnesium. As a result of this electronegativity difference, the carbon atom has a partial negative while magnesium has a partial positive charge. R⁻ᵟ–Mg⁺ᵟX',
 'گرینیارڈ عامل کا کاربن–میگنیشیم بند قطبی نوعیت کا ہے۔ اس کی وجہ کاربن کی میگنیشیم سے زیادہ برقی منفیت ہے۔ اس لیے الیکٹرانی کثافت میگنیشیم کی بجائے کاربن کے قریب ہوتی ہے۔ برقی منفیت کے اس فرق کے نتیجے میں کاربن ایٹم پر جزوی منفی جبکہ میگنیشیم پر جزوی مثبت چارج ہوتا ہے۔ R⁻ᵟ–Mg⁺ᵟX',
 'د ګرینیارډ عامل د کاربن–مګنیزیم تړون قطبي طبیعت لري. دا د مګنیزیم په پرتله د کاربن د لوړ الکترونېګاتیویټي له امله دی. نو الکتروني کثافت د مګنیزیم پر ځای کاربن ته نږدې پروت دی. د الکترونېګاتیویټي د دې توپیر په پایله کې کاربني اټوم نیمګړی منفي او مګنیزیم نیمګړی مثبت چارج لري. R⁻ᵟ–Mg⁺ᵟX')
add('The alkyl group being an electron rich centre, acts as carbanion or nucleophile. It would attack polarized molecules at the point of low electronic density. Therefore, the characteristic reactions of Grignard reagents are nucleophilic substitution and nucleophilic addition reactions.',
 'الکائل گروپ الیکٹرانوں سے بھرپور مرکز ہونے کی وجہ سے کاربینائن یا نیوکلیوفائل کا کام کرتا ہے۔ یہ قطبی سالمات پر کم الیکٹرانی کثافت والے مقام پر حملہ کرتا ہے۔ اس لیے گرینیارڈ عاملین کے خصوصی تعاملات نیوکلیوفائلی تبادلے اور نیوکلیوفائلی اضافے کے تعاملات ہیں۔',
 'الکایل ګروپ د الکترونونو ډک مرکز دی، نو د کاربانیون یا نیوکلیوفایل په توګه عمل کوي. دا پر قطبي مالیکولونو د ټیټ الکتروني کثافت په ځای برید کوي. نو د ګرینیارډ عاملونو ځانګړي تعاملونه نیوکلیوفایلي بدلون او نیوکلیوفایلي اضافي تعاملونه دي.')
